{#- Print Format "Propuestas de Formulación" (BOM Formula, Jinja). Renders every draft Mix
    proposal for this document's product -- scoped to the Pedido given as ?pedido= (the
    report's PDF button; empty = all orders), else to this document's own Sales Order --
    through the Jinja method amb_propuestas_formulacion (amb_w_tds.formulation.propuestas),
    the same function the Script Report uses. TDS per proposal: ?tds= if given, else the
    proposal's own target_tds, else SIN TDS. Values come from the COAs and the gate's last
    Simular; bounds from the TDS. Nothing is hard-coded. -#}
{%- set fd = frappe.form_dict or {} -%}
{%- set pedido = fd.get("pedido") if fd.get("pedido") is not none else (doc.sales_order or None) -%}
{%- set d = amb_propuestas_formulacion(doc.product_sku, pedido or None, fd.get("tds") or None) -%}
{%- macro num(v) -%}{{ "" if v is none else ("%g"|format(v) if v is number else v) }}{%- endmacro -%}
{%- macro hl_label(h) -%}{{ h.label }}{% if h.uniform and h.uom %} ({{ h.uom }}){% endif %}{%- endmacro -%}
{%- macro p_label(h, ph) -%}{{ h.label }}{% if ph.uom %} ({{ ph.uom }}){% endif %}{% if not h.uniform and ph.spec %}<br><span class="small">{{ ph.spec }}</span>{% endif %}{%- endmacro -%}
{%- macro verdict(p) -%}<span class="badge">{{ p.overall }}</span>{% if p.borrador %} <span class="badge">TDS en borrador</span>{% endif %}{%- endmacro -%}
{%- macro spec_table(box) -%}
		<table>
			<tr><th>Parámetro</th><th>Mín</th><th>Máx</th><th>Método de mezcla</th></tr>
			{% for q in box.parameters %}
			<tr><td>{{ q.parameter }}{% if q.uom %} ({{ q.uom }}){% endif %}</td>
				<td class="n">{{ num(q.min) }}</td><td class="n">{{ num(q.max) }}</td><td>{{ q.blend_method }}</td></tr>
			{% endfor %}
		</table>
{%- endmacro -%}
<style>
	.pf-prop { font-size: 9pt; color: #000; }
	.pf-prop h2 { font-size: 13pt; margin: 0 0 4px 0; }
	.pf-prop h3 { font-size: 10.5pt; margin: 14px 0 4px 0; border-bottom: 1px solid #000; }
	.pf-prop table { width: 100%; border-collapse: collapse; margin-bottom: 6px; }
	.pf-prop th, .pf-prop td { border: 1px solid #444; padding: 2px 4px; vertical-align: top; }
	.pf-prop th { background: #eee; font-weight: bold; text-align: left; }
	.pf-prop td.n { text-align: right; }
	.pf-prop .tot td { font-weight: bold; border-top: 2px solid #000; }
	.pf-prop .box { border: 1.5px solid #000; padding: 4px 6px; margin-bottom: 8px; }
	.pf-prop .badge { font-weight: bold; border: 1px solid #000; padding: 0 4px; }
	.pf-prop .muted { color: #333; font-style: italic; }
	.pf-prop .small { font-size: 7.5pt; font-weight: normal; }
	.pf-prop .sig { margin-top: 28px; }
	.pf-prop .sig td { height: 56px; vertical-align: bottom; text-align: center; border: none; }
	.pf-prop .sig .line { border-top: 1px solid #000; padding-top: 2px; }
	.pf-prop .page { page-break-inside: avoid; }
</style>
<div class="pf-prop">
	<h2>Propuestas de Formulación</h2>
	<table>
		<tr><th style="width:18%">Producto</th><td>{{ d.producto }} {{ d.item_name or "" }}</td>
			<th style="width:12%">Pedido</th><td>{{ pedido or "todos" }}</td></tr>
		<tr><th>Fecha de emisión</th><td>{{ frappe.utils.formatdate(frappe.utils.nowdate()) }}</td>
			<th>Propuestas</th><td>{{ d.proposals|length }}</td></tr>
	</table>

	<div class="box">
		<b>Especificación (TDS):</b>
		{% if d.tds %}{{ d.tds.name }}{% if d.tds.status != "aprobada" %} <span class="badge">TDS en {{ d.tds.status }}</span>{% endif %}
		{% if d.tds.source == "filtro" %}<span class="muted">(indicada en el filtro: aplica a todas las propuestas)</span>{% endif %}
		{% if d.tds.usable %}{{ spec_table(d.tds) }}{% endif %}
		{% elif d.proposals %}<span class="muted">por propuesta: cada propuesta se juzga contra su propia TDS objetivo (target_tds); ver la especificación en cada una.</span>
		{% else %}<span class="muted">sin propuestas.</span>{% endif %}
	</div>

	{% for p in d.proposals %}
	<div class="page">
		<h3>Propuesta {{ loop.index }} — {{ p.formula_name }}{% if p.name != p.formula_name %} ({{ p.name }}){% endif %}</h3>
		<div>Cantidad total: <b>{{ num(p.total_kg) }} kg</b> · Tipo: {{ p.formula_type }} · Fecha: {{ frappe.utils.formatdate(p.fecha) if p.fecha else "" }}
			· Cumplimiento: {{ verdict(p) }}</div>
		<div>TDS aplicada: <b>{{ p.tds_label }}</b>{% if p.tds %} <span class="muted">({{ "filtro del reporte" if p.tds.source == "filtro" else "target_tds de la propuesta" }})</span>{% endif %}</div>
		{% if not d.tds and p.tds and p.tds.usable %}
		<div class="box">{{ spec_table(p.tds) }}</div>
		{% endif %}
		<table>
			<tr><th>Lote</th><th>Cantidad (kg)</th>
				{% for h in d.headline %}<th>{{ p_label(h, p.headline[h.key]) }}</th>{% endfor %}
				<th>% mezcla</th></tr>
			{% for ln in p.lines %}
			<tr><td>{{ ln.lote }}{% if not ln.coa %} <span class="muted">(sin COA)</span>{% endif %}</td>
				<td class="n">{{ num(ln.kg) }}</td>
				{% for h in d.headline %}<td class="n">{{ num(ln["values"][h.key]) if ln.coa else "" }}</td>{% endfor %}
				<td class="n">{{ num(ln.pct) }}</td></tr>
			{% endfor %}
			<tr class="tot"><td>TOTAL (puerta)</td><td class="n">{{ num(p.total_kg) }}</td>
				{% for h in d.headline %}<td class="n">{{ num(p.total[h.key]) }}</td>{% endfor %}
				<td></td></tr>
			{% if p.tds and p.tds.usable %}
			<tr><td colspan="2"><b>Cumplimiento</b></td>
				{% for h in d.headline %}<td>{{ d.mark(p.total_ok[h.key]) if p.headline[h.key].spec else "" }}</td>{% endfor %}
				<td></td></tr>
			{% endif %}
		</table>
		{% if p.compliance %}
		<table>
			<tr><th>Parámetro ({{ p.tds_label }})</th><th>Predicho</th><th>Mín</th><th>Máx</th><th>Cumplimiento</th></tr>
			{% for c in p.compliance %}
			<tr><td>{{ c.parameter }}{% if c.uom %} ({{ c.uom }}){% endif %}</td>
				<td class="n">{{ num(c.value) if c.value is not none else "sin dato" }}</td>
				<td class="n">{{ num(c.min) }}</td><td class="n">{{ num(c.max) }}</td>
				<td>{{ "descriptivo — laboratorio" if c.kind == "descriptive" else d.mark(c.ok) }}</td></tr>
			{% endfor %}
		</table>
		{% endif %}
		{% if p.notes %}<div class="muted">{{ p.notes|join("; ") }}</div>{% endif %}
	</div>
	{% else %}
	<p class="muted">No hay propuestas Mix en borrador para este producto{% if pedido %} y pedido{% endif %}.</p>
	{% endfor %}

	<div class="page">
	{% if d.proposals %}
	<h3>Comparativo para decisión</h3>
	<table>
		<tr><th>Propuesta</th><th>TDS aplicada</th><th>Cantidad (kg)</th>
			{% for h in d.headline %}<th>{{ hl_label(h) }}</th>{% endfor %}
			<th>Cumple</th><th>N° lotes</th></tr>
		{% for p in d.proposals %}
		<tr style="page-break-inside: avoid"><td>{{ loop.index }}. {{ p.formula_name }}</td><td>{{ p.tds_label }}</td>
			<td class="n">{{ num(p.total_kg) }}</td>
			{% for h in d.headline %}<td class="n">{{ num(p.total[h.key]) }}{% if not h.uniform and p.headline[h.key].spec %}<br><span class="small">{{ p.headline[h.key].spec }}{% if p.headline[h.key].uom %} ({{ p.headline[h.key].uom }}){% endif %}</span>{% endif %}</td>{% endfor %}
			<td><b>{{ "sí" if p.overall == "CUMPLE" else "no" }}</b>{% if p.overall not in ("CUMPLE", "NO CUMPLE") %} ({{ p.overall }}){% endif %}{% if p.borrador %}<br><span class="small">TDS en borrador</span>{% endif %}</td>
			<td class="n">{{ p.n_lotes }}</td></tr>
		{% endfor %}
	</table>
	{% endif %}

	<h3>Decisión de Dirección</h3>
	<div>
		{% for p in d.proposals[:3] %}☐ Propuesta {{ loop.index }} &nbsp;&nbsp; {% endfor %}☐ Otra: ______________________
	</div>
	<table class="sig">
		<tr><td><div class="line">Aprobó (Dirección)</div></td>
			<td><div class="line">Revisó (Control de Calidad)</div></td>
			<td><div class="line">Elaboró (Formulación)</div></td></tr>
	</table>
	<div class="muted">Valores estimados por la puerta (Simular); la liberación requiere el valor medido del lote mezclado.{% if d.proposals|selectattr("borrador")|list %} Un veredicto marcado "TDS en borrador" usa límites aún no aprobados.{% endif %}</div>
	</div>
</div>
